WITH exploded AS (SELECT id, customer_id, created_at, coupon_codes, pos, item.product_id, item.qty, item.price, item.promo FROM carts LATERAL VIEW OUTER POSEXPLODE(items) t AS pos, item), lines AS (SELECT id, customer_id, created_at, promo, tag FROM exploded LATERAL VIEW OUTER EXPLODE(coupon_codes) li AS tag), valid AS (SELECT promo, QUARTER(created_at) AS created_at_quarter, INITCAP(TRIM(tag)) AS tag_title, COALESCE(tag, 'OTHER') AS resolved_tag FROM lines WHERE created_at >= DATE '2025-03-02' AND promo IS NOT NULL), metrics AS (SELECT *, STDDEV_SAMP(created_at_quarter) OVER (PARTITION BY promo) AS promo_stddev_samp_created_at_quarter FROM valid) SELECT CASE WHEN promo_stddev_samp_created_at_quarter >= 82 THEN 'LARGE' ELSE 'SMALL' END AS promo_stddev_samp_created_at_quarter_tier, SUM(CASE WHEN promo = 'SPRING10' THEN promo_stddev_samp_created_at_quarter ELSE 0 END) AS spring10_promo_stddev_samp_created_at_quarter, SIZE(COLLECT_SET(promo)) AS num_promos FROM metrics GROUP BY promo_stddev_samp_created_at_quarter_tier
